// Fields allowed in the request body
const ALLOWED_FIELDS = [
  'productTypes',
  'personalInformation',
  'loanInformation',
  'mortgageInformation',
  'creditInformation',
  'financialInformation',
  'educationInformation',
  'legalInformation',
  'sessionInformation'
];

// Format the date of birth to YYYY-MM-DD with zero-padded month/day
function formatDateOfBirth(dateString) {
  if (!dateString) return dateString;

  // Split the date string by hyphens
  const parts = dateString.split('-');

  // Check if we have exactly 3 parts (year, month, day)
  if (parts.length !== 3) return dateString;

  const [year, month, day] = parts;

  // Pad month and day with leading zeros if needed
  const paddedMonth = month.padStart(2, '0');
  const paddedDay = day.padStart(2, '0');

  return `${year}-${paddedMonth}-${paddedDay}`;
}

// Remove fields that are not in the allowed list
function sanitizeRequestBody(body) {
  const sanitizedBody = {};

  for (const field of ALLOWED_FIELDS) {
    if (field in body) {
      sanitizedBody[field] = body[field];
    }
  }

  return sanitizedBody;
}

// Apply hardcoded defaults and override values in the request body
function applyBusinessDefaults(body) {
  const result = {
    ...body,
    // Override product types to loans only
    productTypes: ['loan'],

    // Ensure legal information structure and set TCPA consent
    legalInformation: {
      ...body.legalInformation,
      consentsToTcpa: false
    },

    // Ensure credit information structure and set default rating
    creditInformation: {
      ...body.creditInformation,
      providedCreditRating: body.creditInformation?.providedCreditRating || 'fair'
    }
  };

  // Format date of birth if present
  if (result.personalInformation?.dateOfBirth) {
    result.personalInformation = {
      ...result.personalInformation,
      dateOfBirth: formatDateOfBirth(result.personalInformation.dateOfBirth)
    };
  }

  return result;
}

// Single request attempt, no retry logic here
async function makeRequest(body) {
  const url = 'https://integrations.evenfinancial.com/blocking/leads/rateTables';
  const headers = {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${env.ENGINE_API_PRODUCTION_TOKEN}`,
  };

  console.log(body);

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify(body)
    });

    // Parse the response body: JSON when possible, raw text otherwise
    const text = await response.text();
    let data;
    try {
      data = JSON.parse(text);
    } catch {
      data = text;
    }

    // For successful responses (200 or 201), return the response body as is
    if (response.status === 200 || response.status === 201) {
      return {
        error: false,
        statusCode: response.status,
        data: data,
      };
    }

    // Other 2xx statuses (axios resolved these without throwing)
    if (response.status >= 200 && response.status < 300) {
      return {
        error: true,
        statusCode: response.status,
        message: data?.message,
      };
    }

    // Non-2xx: the server responded with an error status.
    // Mirrors axios: message is the full response body, or the
    // axios-style fallback when the body is empty.
    return {
      error: true,
      statusCode: response.status,
      message: data || `Request failed with status code ${response.status}`
    };
  } catch (error) {
    console.log(error);

    // fetch threw, so no response was received
    return {
      error: true,
      statusCode: 503,
      message: 'No response received from the server'
    };
  }
}

// Wrapper function that handles retry logic
async function makeRequestWithRetry(body) {
  // First attempt
  console.log("Making initial request to Engine...");
  let result = await makeRequest(body);

  // If first attempt failed with 5xx error, retry once after 150ms
  if (result.error && result.statusCode >= 500 && result.statusCode < 600) {
    console.log(`First request failed with ${result.statusCode}, retrying after 150ms...`);

    // Wait 150ms
    // await new Promise(resolve => setTimeout(resolve, 150));

    // Retry the request
    console.log("Making retry request to Engine...");
    result = await makeRequest(body);

    if (result.error) {
      console.log(`Retry also failed with status ${result.statusCode}`);
    } else {
      console.log("Retry request succeeded!");
    }
  }

  return result;
}

// Ported from Pipedream send_request_to_engine (submission id added 7-10-26)
const body = { ...trigger.payload };
const sanitizedBody = sanitizeRequestBody(body);
const processedBody = applyBusinessDefaults(sanitizedBody);

// Add clientTags
if (body.Submission__c) {
  processedBody.clientTags = {
    clientId: [body.Submission__c],
  };
}

console.log('Processed request body:', processedBody);

return await makeRequestWithRetry(processedBody);

// Builds the submit link the agent's Slack message carries (#2092). trypennie.com refuses
// it for a submission created after its cutoff unless it carries the link token, and a
// webhook node cannot sign, so this node signs it and send_to_slack_agent sends
// steps.sign_submission_link.output.url.
// The hosts that get the link token (#2092): the block below signs a link to these only.
const LINK_TOKEN_HOSTS = ['trypennie.com', 'www.trypennie.com'];
// BEGIN link token (#2089)
// trypennie.com refuses a link to a Salesforce record created after its cutoff unless the
// link carries ?t=<token>: HMAC-SHA256 of the first 15 characters of the record id, keyed
// with LINK_TOKEN_SECRET, base64url with no padding, and reservemyloan.com is to check the
// same token. Salesforce's LinkToken class and the Pipedream helpers sign exactly the same
// way. Only a host in LINK_TOKEN_HOSTS, which each script sets just above this block, gets
// the token, never a partner's domain. With no secret the link goes out unsigned, an error
// is logged and `link_token` on this step's output says why; the run is never failed for
// it. This block is identical in every script that signs a link, and link-token.test.ts
// holds them all to one text (#2092).
const SALESFORCE_ID = /^[a-zA-Z0-9]{15}(?:[a-zA-Z0-9]{3})?$/;
const withLinkToken = async (url, recordId) => {
  let host = null;
  try { host = new URL(url).hostname; } catch {}
  if (!LINK_TOKEN_HOSTS.includes(host)) return { url, link_token: 'not_our_host' };
  if (typeof recordId !== 'string' || !SALESFORCE_ID.test(recordId)) return { url, link_token: 'no_record_id' };
  const secret = env.LINK_TOKEN_SECRET;
  if (typeof secret !== 'string' || !secret) {
    console.error('LINK_TOKEN_SECRET is not set, so the link went out without its token (#2089)');
    return { url, link_token: 'missing_secret' };
  }
  try {
    const enc = new TextEncoder();
    const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    const signature = new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode(recordId.slice(0, 15))));
    let binary = '';
    for (const byte of signature) binary += String.fromCharCode(byte);
    const token = btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    return { url: `${url}${url.includes('?') ? '&' : '?'}t=${token}`, link_token: 'signed' };
  } catch (err) {
    console.error(`signing the link failed, so it went out without its token (#2089): ${err && err.message}`);
    return { url, link_token: 'sign_failed' };
  }
};
// END link token (#2089)

const submissionId = trigger.payload.Submission__c ?? '';
const submissionLink = await withLinkToken(`https://trypennie.com/submit?submission_id=${submissionId}`, submissionId);
return { url: submissionLink.url, link_token: submissionLink.link_token };
